import json

# Primes below 2015 (used to test the "no prime divisor less than 2015" rule).
def primes_below(m):
    sieve = [True] * m
    sieve[0] = sieve[1] = False
    for i in range(2, int(m ** 0.5) + 1):
        if sieve[i]:
            for j in range(i * i, m, i):
                sieve[j] = False
    return [i for i in range(m) if sieve[i]]

SMALL = primes_below(2015)

def valid_n(n):
    # n = 1 has no prime divisor at all; n > 1 must have no prime factor below 2015.
    if n == 1:
        return True
    return all(n % p for p in SMALL)

# Candidate n values: admissible n in a finite window, first 40 of them.
cands = []
for n in range(1, 20000):
    if valid_n(n):
        cands.append(n)
        if len(cands) == 40:
            break

B = 30  # exhaustive bound on a, b, c in natural numbers 1..B

sols = []
for a in range(1, B + 1):
    for b in range(1, B + 1):
        for c in range(1, B + 1):
            ok = True
            for n in cands:
                m = n + c
                if (pow(a, n, m) + pow(b, n, m) + n) % m != 0:
                    ok = False
                    break
            if ok:
                sols.append((a, b, c))

if sols == [(1, 1, 2)]:
    final_answer = "(a,b,c) = (1,1,2)"
else:
    final_answer = "UNSUPPORTED"

evidence = {
    "bound_B": B,
    "num_candidate_n": len(cands),
    "first_candidate_n": cands[:6],
    "survivors_in_bound": [list(t) for t in sols],
    "argument": "For prime p=n+c large, Fermat gives a^(1-c)+b^(1-c)=c; c=1 fails, c>=3 gives LHS<=2<c, c=2 forces a=b=1",
}

print(json.dumps({"final_answer": final_answer, "evidence": evidence}))
